# keyword-as-name differential fuzz: registry includes keyword names
import random, sys
sys.path[:0]=['/workspace/tmp/tests','/opt/emicro-deps','/workspace/project']
from brute import compare
NAMES=['and','or','match','not','A','allow']
rng=random.Random(5)
labels=rng.sample(range(1,4294967294),len(NAMES))
reg=[{'name':n,'label':labels[i]} for i,n in enumerate(NAMES)]
def gen_path(m): return ','.join(rng.choice(NAMES) for _ in range(rng.randint(0,3)))
def gen_pred(d):
    if d>=3 or rng.random()<0.45:
        return '%s(%s)'%(rng.choice(['match','match','startswith','endswith','contains']),gen_path(3))
    if rng.random()<0.2: return 'not(%s)'%gen_pred(d+1)
    return '(%s %s %s)'%(gen_pred(d+1),rng.choice(['and','or']),gen_pred(d+1))
bad=skip=done=0
for i in range(150):
    p=' '.join('%s %s;'%(gen_pred(0),rng.choice(['allow','drop'])) for _ in range(rng.randint(0,3)))
    try:
        ok=compare(p,reg,dw=4,dc=4,verbose=(bad<2))
    except Exception as e:
        skip+=1; continue
    done+=1
    if not ok:
        bad+=1; print('FAIL',repr(p))
print('keyword-name fuzz checked',done,'bad',bad,'skip',skip)
EOF
